docs.src1:
source:
  - name: p1
    type: POINT
    position: 100 0 50
    inventory:
      - {nuclide: Co60, radioactivity: 1.0e+10}
      - {nuclide: Cs137, radioactivity: 2e9}
    cutoff_rate: 1.0e-5
    path_trace:
      position: [1 2 3, 4 5 6]
      bounding_box: [b1]
  - {type: BOX, name: box1, geometry: {vertex: 0 0 0, edge_1: 10 0 0, edge_2: 0 20 0, edge_3: 0 0 30, transform: tr1}, division: {edge_1: {type: UNIFORM, number: 5}, edge_2: {type: GAUSS_FIRST, number: 4, min: 0.1, max: 0.9}, edge_3: {type: MANUAL, end_point: 0 0.3 1, weight: 2 1}}, inventory: [{energy: 1.25, spectrum: 1, radioactivity: 3e8}], cutoff_rate: 0.001}
  - type: sph
    name: ball
    geometry: {center: 0 0 0, radius: 5}
    division:
      r: {type: UNIFORM, number: 3}
      theta: {type: UNIFORM, number: 4, min: 0, max: 90}
      phi: {type: MANUAL, end_point: 0 0.5 1}
    inventory:
      - {nuclide: Co60, radioactivity: 1}
  - {type: RCC, name: cyl, geometry: {bottom_center: 0 0 0, height_vector: 0 0 10, radius: 2, transform: tr2}, division: {r: {type: UNIFORM, number: 2}, phi: {type: UNIFORM, number: 2}, z: {type: GAUSS_BOTH, number: 6}}, inventory: [{nuclide: Co60, radioactivity: 5}]}

